/// <summary>
/// Controller of the periodic mass trade agreement price update.
/// </summary>
public class DYLO_TradeAgreementPriceAdjController extends SysOperationServiceController
{
}

Method.Source:
public static DYLO_TradeAgreementPriceAdjController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    return new DYLO_TradeAgreementPriceAdjController(_executionMode);
}

public static void main(Args _args)
{
    DYLO_TradeAgreementPriceAdjController controller = DYLO_TradeAgreementPriceAdjController::construct();

    controller.parmArgs(_args);
    controller.startOperation();
}
